    :TM133 => ['TM133', 'Beißt mit flammenden Reißzähnen. Kann Ziel verbrennen oder zum zurückschrecken bringen.', 'TM133', 'TM133', 'Beißt mit flammenden Reißzähnen. Kann Ziel verbrennen oder zum Zurückschrecken bringen.', 'Beißt mit flammenden Reißzähnen zu. Kann das Ziel verbrennen oder zurückschrecken lassen.', 'Beißt mit flammenden Reißzähnen. Kann Ziel verbrennen oder zum zurückschrecken bringen.'],
    :TM154 => ['TM154', 'Wickelt Gegner in heftigen Wirbel. Kann Ziel verwirren.', 'TM154', 'TM154', 'Wickelt Gegner in heftigen Wirbel. Kann Ziel verwirren.', 'Umhüllt das Ziel mit einem heftigen Wirbelsturm. Kann es verwirren.', 'Wickelt Gegner in heftigen Wirbel. Kann Ziel verwirren.'],
    :TM157 => ['TM157', 'Entzündet sich und rast vor. Erleidet schweren Rückstoßschaden. Kann Ziel verbrennen.', 'TM157', 'TM157', 'Entzündet sich und rast vor. Erleidet schweren Rückstoßschaden. Kann Ziel verbrennen.', 'Rammt das Ziel in Flammen. Starker Rückstoßschaden. Kann das Ziel verbrennen.', 'Entzündet sich und rast vor. Erleidet schweren Rückstoßschaden. Kann Ziel verbrennen.'],
    :TM163 => ['TM163', 'Wackelt mit Finger. löst zufällige Auswahl nahezu jeder Attacke aus.', 'TM163', 'TM163', 'Wackelt mit Finger. löst zufällige Auswahl nahezu jeder Attacke aus.', 'Der Anwender wackelt mit einem Finger und setzt dadurch zufällig eine von sehr vielen Attacken ein.', 'Wackelt mit Finger. löst zufällige Auswahl nahezu jeder Attacke aus.'],
    :TM164 => ['TM164', 'Leert kurz den Geist. Erhöht Sp. Vert. stark.', 'TM164', 'TM164', 'Leert kurz den Geist. Erhöht Sp. Vert. stark.', 'Der Anwender vergisst seine Sorgen und erhöht seine Spezial-Verteidigung stark.', 'Leert kurz den Geist. Erhöht Sp. Vert. stark.'],
    :TM169 => ['TM169', 'Wechselt mit einem ruhenden Team-Pokémon und überträgt Stat.-Änderungen.', 'TM169', 'TM169', 'Wechselt mit einem ruhenden Team-Pokémon und überträgt Stat.-Änderungen.', 'Der Anwender wechselt mit einem Pokémon aus dem Team und überträgt dabei seine Statuswertänderungen.', 'Wechselt mit einem ruhenden Team-Pokémon und überträgt Stat.-Änderungen.'],
    :TM185 => ['TM185', 'Spielt rau und greift an. Kann Ang. des Ziels senken.', 'TM185', 'TM185', 'Spielt rau und greift an. Kann Ang. des Ziels senken.', 'Greift das Ziel verspielt, aber heftig an. Kann dessen Angriff senken.', 'Spielt rau und greift an. Kann Ang. des Ziels senken.'],
    :TM189 => ['TM189', 'Setzt Pollenpuff ein: explodiert bei Gegnern, heilt Verbündete.', 'TM189', 'TM189', 'Setzt Pollenpuff ein: explodiert bei Gegnern, heilt Verbündete.', 'Greift Gegner mit einem Pollenknödel an. Auf Verbündete angewendet, stellt die Attacke KP wieder her.', 'Setzt Pollenpuff ein: explodiert bei Gegnern, heilt Verbündete.'],
    :TM191 => ['TM191', 'Rächt einen gefallenen Verbündeten. Fiel letzte Runde ein Verb., steigt Schaden.', 'TM191', 'TM191', 'Rächt einen gefallenen Verbündeten. Fiel letzte Runde ein Verb., steigt Schaden.', 'Rächt besiegte Mitstreiter. Stärker, wenn in der letzten Runde ein Verbündeter besiegt wurde.', 'Rächt einen gefallenen Verbündeten. Fiel letzte Runde ein Verb., steigt Schaden.'],
    :TM196 => ['TM196', 'Trifft Ziel mit Farbstrahl. Kann Ang. des Ziels senken.', 'TM196', 'TM196', 'Trifft Ziel mit Farbstrahl. Kann Ang. des Ziels senken.', 'Beschießt das Ziel mit kaltem Wasser und senkt dessen Angriff.', 'Trifft Ziel mit Farbstrahl. Kann Ang. des Ziels senken.'],
    :TM203 => ['TM203', 'Das Ziel wird mit großer Wucht zerquetscht. Je mehr KP es noch hat, desto stärker ist die Attacke.', 'TM203', 'TM203', 'Das Ziel wird mit großer Wucht zerquetscht. Je mehr KP es noch hat, desto stärker ist die Attacke.', 'Zerquetscht das Ziel mit großer Wucht. Je mehr KP es noch hat, desto stärker ist die Attacke.', 'Das Ziel wird mit großer Wucht zerquetscht. Je mehr KP es noch hat, desto stärker ist die Attacke.'],
    :TM212 => ['TM212', 'Bläst eine mächtige Böe und verursacht Schaden; Kann das Ziel paralysieren.', 'TM212', 'TM212', 'Bläst eine mächtige Böe und verursacht Schaden; Kann das Ziel paralysieren.', 'Bläst dem Ziel einen mächtigen Hauch entgegen. Kann es paralysieren.', 'Bläst eine mächtige Böe und verursacht Schaden; Kann das Ziel paralysieren.'],
    :TM214 => ['TM214', 'Lässt charmanten Ruf ertönen und fügt Gegnern emotionalen Schaden. Verfehlt nie.', 'TM214', 'TM214', 'Lässt charmanten Ruf ertönen und fügt Gegnern emotionalen Schaden. Verfehlt nie.', 'Greift mit einer betörenden Stimme an. Diese Attacke trifft immer.', 'Lässt charmanten Ruf ertönen und fügt Gegnern emotionalen Schaden. Verfehlt nie.'],
    :TM221 => ['TM221', 'Wankt umher. wird stärker, je weniger KP der Anwender hat.', 'TM221', 'TM221', 'Wankt umher. wird stärker, je weniger KP der Anwender hat.', 'Der Anwender schlägt unkontrolliert um sich. Je weniger KP er hat, desto stärker ist die Attacke.', 'Wankt umher. wird stärker, je weniger KP der Anwender hat.'],
    :TM229 => ['TM229', 'Schickt klingenartigen Wind auf dem Gegner. Hohe Volltrefferquote.', 'TM229', 'TM229', 'Schickt klingenartigen Wind auf dem Gegner. Hohe Volltrefferquote.', 'Schickt scharfe Windklingen auf das Ziel. Die Attacke hat eine hohe Volltrefferquote.', 'Schickt klingenartigen Wind auf dem Gegner. Hohe Volltrefferquote.'],
    :TM241 => ['TM241', 'Zieht den Kopf ein, rammt das Ziel in der nächsten Runde.', 'TM241', 'TM241', 'Zieht den Kopf ein, rammt das Ziel in der nächsten Runde.', 'Der Anwender zieht den Kopf ein und erhöht seine Verteidigung. In der nächsten Runde rammt er das Ziel.', 'Zieht den Kopf ein, rammt das Ziel in der nächsten Runde.'],
