  def self.german?
    MessageTypes.class_variable_get(:@@messages).instance_variable_get(:@german_item_review_enabled)
  end
  def self.repair(section, source, value)
    pair = LOOKUPS[[section, source]]
    pair && value == pair[0] ? pair[1] : value
  end
  def self.item_id(item)
    item.is_a?(Integer) ? $cache.items.keys[item - 1] : item
  end
  def self.item_text(item, value, description)
    return value unless german?
    id = item_id(item)
    row = ITEMS[id]
    data = $cache.items[id]
    return value unless row && data && data.name == row[0] && data.desc == row[1]
    if description && row[6]
      move = data.checkFlag?(:tm)
      return value unless move && $cache.moves[move] && $cache.moves[move].desc == row[6]
    end
    before, after = description ? row[4, 2] : row[2, 2]
    value == before ? after : value
  end
  module Lookup
    def loadMessageFile(filename)
      @german_item_review_enabled = false
      result = super
      @german_item_review_enabled = !!result && File.basename(filename.to_s.tr('\\', '/')).downcase == 'german.dat'
      result
    end
    def getFromHash(section, source)
      value = super
      return value unless @german_item_review_enabled
      GermanItemReview.repair(section, source, value)
    end
  end
  module ItemDisplay
    def getItemName(item)
      GermanItemReview.item_text(item, super, false)
    end
    def getItemDescription(item)
      GermanItemReview.item_text(item, super, true)
    end
    def pbChooseItemFromList(message, variable, *args)
      return super unless GermanItemReview.german?
      items = args.select { |item| $PokemonBag.pbQuantity(item) > 0 }
      if items.empty?
        $game_variables[variable] = 0
        return nil
      end
      commands = items.map { |item| getItemName(item) }
      commands.push(_INTL('Cancel'))
      ret = Kernel.pbMessage(message, commands, -1)
      if ret < 0 || ret >= items.length
        $game_variables[variable] = -1
        return nil
      end
      $game_variables[variable] = items[ret]
      items[ret]
    end
  end
end
Messages.prepend(GermanItemReview::Lookup) unless Messages.ancestors.include?(GermanItemReview::Lookup)
Object.prepend(GermanItemReview::ItemDisplay) unless Object.ancestors.include?(GermanItemReview::ItemDisplay)

